`include "ascon_model.vh"
// Generated by ascon_designspace.generator.permutation
// Iterative ASCON permutation, 1 round(s) per cycle.
// rounds_i: 0=p6 (idx 10..15), 1=p8 (8..15), 2=p12 (4..15).
module ascon_perm_iter_r1 (
  input  wire         clk,
  input  wire         rst_n,
  input  wire         start_i,
  input  wire [1:0]   rounds_i,
  input  wire [319:0] state_i,
  output reg  [319:0] state_o,
  output reg          valid_o,
  output wire         busy_o
);
  localparam [4:0] DONE = 5'd16;

  function [4:0] start_index;
    input [1:0] rr;
    begin
      case (rr)
        2'd0: start_index = 5'd10; // p6
        2'd1: start_index = 5'd8;  // p8
        2'd2: start_index = 5'd4;  // p12
        default: start_index = DONE;
      endcase
    end
  endfunction

  // Combinational block of up to 1 guarded rounds.
  function [319:0] r_rounds;
    input [319:0] s_in;
    input [4:0]   idx_in;
    reg   [319:0] t;
    begin
      t = s_in;
      if ((idx_in + 5'd0) < DONE) t = ascon_round_const_index(t, (idx_in + 5'd0)); 
      r_rounds = t;
    end
  endfunction

  reg [319:0] s;
  reg [4:0]   idx;
  reg         running;

  // Single combinational instance of the R-round block, shared by the state
  // update and the final-result capture (so the round logic is not duplicated).
  wire [319:0] next_s = r_rounds(s, idx);

  assign busy_o = running;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      running <= 1'b0;
      valid_o <= 1'b0;
      idx     <= DONE;
      s       <= 320'b0;
      state_o <= 320'b0;
    end else begin
      valid_o <= 1'b0;
      if (start_i) begin
        s       <= state_i;
        idx     <= start_index(rounds_i);
        running <= 1'b1;
      end else if (running) begin
        s <= next_s;
        if ((idx + 5'd1) >= DONE) begin
          state_o <= next_s;
          valid_o <= 1'b1;
          running <= 1'b0;
        end else begin
          idx <= idx + 5'd1;
        end
      end
    end
  end
endmodule
